with cleaned as (select *, add_months(hire_date, 3) as hire_date_plus_months, round(salary * 1.1, 2) as adjusted_salary, coalesce(job_title, 'OTHER') as resolved_job_title from employees where hire_date >= date '2023-02-13' and email is not null) select id, full_name, email, salary, hire_date_plus_months, sum(salary) over (partition by manager_id, dept_id order by adjusted_salary, id rows between unbounded preceding and current row) as cumulative_salary, avg(salary) over (partition by job_title order by hire_date_plus_months, id rows between 2 preceding and 1 preceding) as salary_avg_2_prior, row_number() over (order by adjusted_salary, id) as seq_no, row_number() over w_recent as row_seq, avg(salary) over (partition by job_title, level order by salary, id rows between 3 preceding and 1 preceding) as salary_avg_3_prior from cleaned window w_recent as (partition by manager_id order by hire_date, id);
